with open('/work/secret.enc', 'rb') as f:
    encrypted = f.read()

def is_printable(s):
    return all(32 <= b < 127 for b in s) or all(9 <= b <= 13 for b in s)

for key in range(256):
    decrypted = bytes([b ^ key for b in encrypted])
    if is_printable(decrypted):
        print(f"\nKey {key:02x}:")
        print(decrypted.decode('ascii'))
EOF
